The `capture_stack` function redirects the global DPDK log stream using `rte_openlog_stream` to capture the stack trace. Since `rte_openlog_stream` modifies global state, concurrent calls to `capture_stack` from multiple threads will race, leading to mixed output, log corruption, or potential crashes (e.g., writing to a closed stream). Protect this redirection with a static mutex to ensure thread safety.

```go
/*
#define _GNU_SOURCE
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>

extern void rte_dump_stack(void);
extern int rte_openlog_stream(FILE *);

static pthread_mutex_t capture_mu = PTHREAD_MUTEX_INITIALIZER;

// Keep an observable caller without changing the archive's optimization flags.
static __attribute__((noinline)) int capture_stack(char **text) {
    pthread_mutex_lock(&capture_mu);
    size_t size;
    FILE *stream = open_memstream(text, &size);
    if (stream == NULL) {
        pthread_mutex_unlock(&capture_mu);
        return -1;
    }
    rte_openlog_stream(stream);
    rte_dump_stack();
    rte_openlog_stream(NULL);
    int ret = fclose(stream);
    pthread_mutex_unlock(&capture_mu);
    return ret;
}
*/
```

